excels.excel:

EXPORT WITH SHEET="售后客诉质量分析表", HEADER=true,
    MAPPING={"a":"产品型号","b":"销售量","c":"客诉数量","d":"严重客诉","e":"客诉率","f":"严重客诉占比","g":"责任部门"},
    FORMAT={"b":"#,##0","c":"#,##0","d":"#,##0","e":"0.00%","f":"0.00%"},
    FORMULAS={
        E2:'C2/B2',F2:'D2/C2',E3:'C3/B3',F3:'D3/C3',E4:'C4/B4',F4:'D4/C4',
        E5:'C5/B5',F5:'D5/C5',E6:'C6/B6',F6:'D6/C6',E7:'C7/B7',F7:'D7/C7',
        B8:'SUM(B2:B7)',C8:'SUM(C2:C7)',D8:'SUM(D2:D7)',E8:'C8/B8',F8:'D8/C8'
    },
    STYLE={
        ROW 8:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right,verticalAlignment:center},
        E4:{color:red,bold:true}
    }
